SELECT DISTINCT doctor_id
FROM doctor_schedule_slot
WHERE doctor_id IN

    #{doctorId}

  AND schedule_date BETWEEN #{startDate} AND #{endDate}
  AND status = 'OPEN'
  AND remaining_capacity > 0
  AND (schedule_date > #{currentDate}
       OR (schedule_date = #{currentDate} AND end_time > #{currentTime}))

SELECT id, schedule_date, session_type, session_name, start_time, end_time,
       total_capacity, remaining_capacity
FROM doctor_schedule_slot
WHERE doctor_id = #{doctorId}
  AND schedule_date BETWEEN #{startDate} AND #{endDate}
  AND status = 'OPEN'
  AND (schedule_date > #{currentDate}
       OR (schedule_date = #{currentDate} AND end_time > #{currentTime}))
ORDER BY schedule_date ASC, start_time ASC, id ASC
